// استخراج تقرير الذكاء الاصطناعي وتطبيق مصفوفة القواعد وحالات الفشل
const geminiRaw = $input.first().json;
const candidateText = geminiRaw.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleanJson = candidateText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let aiData = {};
try {
  aiData = JSON.parse(cleanJson);
} catch(e) {
  aiData = { is_valid_receipt: false, reason: 'فشل قراءة النص' };
}

// جلب المبلغ المطلوب للطلب (مثال من السجل)
const requiredAmount = 85.0; // يتم ربطه برقم طلب العميل من الشيت
const paidAmount = Number(aiData.amount_paid || 0);

let decisionCode = 'FAILED';
let reason = '';

if (!aiData.is_valid_receipt) {
  decisionCode = 'INVALID_IMAGE';
  reason = 'الصورة المرسلة ليست إيصال دفع صحيح.';
} else if (aiData.tampering_signs && aiData.tampering_signs.detected) {
  decisionCode = 'TAMPERED';
  reason = 'تم رصد شبهة تعديل أو تلاعب في أرقام وخطوط الإيصال.';
} else if (aiData.is_today_or_recent === false) {
  decisionCode = 'EXPIRED';
  reason = 'تاريخ التحويل في الإيصال قديم ولا يطابق وقت هذا الطلب.';
} else if (paidAmount < requiredAmount) {
  decisionCode = 'PARTIALLY_PAID';
  reason = `تم استلام ${paidAmount} ج.م ومتبقي ${requiredAmount - paidAmount} ج.م لتأكيد الطلب.`;
} else if (paidAmount > requiredAmount) {
  decisionCode = 'OVERPAID_CONFIRMED';
  reason = `تم السداد بزيادة ${paidAmount - requiredAmount} ج.م وسيتم رد الفارق نقداً.`;
} else {
  decisionCode = 'PAID_CONFIRMED';
  reason = 'تم التحقق من صحة الإيصال والمبلغ وتطابق البيانات بنجاح 100%.';
}

return {
  decisionCode,
  reason,
  aiData,
  paidAmount,
  requiredAmount,
  chatId: $('5. تليجرام Trigger (استقبال رسائل وصور العملاء)').first().json.message.chat.id
};

